mapper.select:
select l.link_id, l.code, l.source_id, l.file_path, l.file_name, l.file_ext, l.file_size, l.content_type, l.storage_type, l.storage_location, l.password_hash, l.expire_at, l.max_views, l.view_count, l.burn_after_read, l.cache_status, l.cache_error, l.cache_retry_count, l.status, l.last_view_time, l.create_by, l.create_time, l.update_by, l.update_time, l.remark, s.name as source_name from share_link l left join share_source s on s.source_id = l.source_id
AND l.file_name like concat('%', #{fileName}, '%')
AND l.code = #{code}
AND l.source_id = #{sourceId}
AND l.status = #{status}
AND l.cache_status = #{cacheStatus}
order by l.link_id desc

mapper.update:
update share_link
password_hash = #{passwordHash}, expire_at = #{expireAt}, max_views = #{maxViews}, burn_after_read = #{burnAfterRead}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where link_id = #{linkId}

update share_link
set cache_status = #{to}, update_time = sysdate()
where link_id = #{linkId} and cache_status = #{from}

update share_link
set cache_status = '0', cache_error = '', update_time = sysdate()
where link_id = #{linkId}

update share_link
set view_count = 0, cache_status = '0', cache_error = '', update_time = sysdate()
where link_id = #{linkId}

mapper.select:

where l.cache_status in ('0', '3') and l.cache_retry_count < #{maxRetry}
order by l.link_id asc
limit #{limit}
